import {
  Box,
  Card,
  CardContent,
  Container,
  Grid,
  Typography,
} from "@mui/material";
import React from "react";
import { useState } from "react";
import ScrollAnimation from "react-animate-on-scroll";
import "../../../styles/animation.css";
import { useEffect } from "react";
import { useRef } from "react";
import ellipseImg1 from "../../../assets/images/Ellipse1cards.png";
import ellipseImg2 from "../../../assets/images/Ellipse2cards.png";
import { Link } from "react-router-dom";

const UnlockFutureInnovation = () => {
  const innovations = [
    {
      title: "Request Quote",
      description:
        "Upgrade, renew, or unlock the full potential of ManageEngine with competitive pricing and hassle-free licensing.",
      path: "/it-solution-getQuote/:id",
    },
    {
      title: "Request a Demo",
      description:
        "Experience ManageEngine in action and receive tailored expert advice for your unique challenges.",
      path: "/it-solution-demo/:id",
    },
    {
      title: "Download a free 30 Day Trail",
      description:
        "Discover firsthand the transformative power and user-friendly experience of ManageEngine.",
    },
  ];

  const [visibleIndices, setVisibleIndices] = useState([]);
  const [isInView, setIsInView] = useState(false);
  const cardsRef = useRef([]);
  const containerRef = useRef(null);

  useEffect(() => {
    const observer = new IntersectionObserver(
      (entries) => {
        entries.forEach((entry) => {
          if (entry.isIntersecting) {
            const index = cardsRef.current.indexOf(entry.target);
            if (index !== -1 && !visibleIndices.includes(index)) {
              setVisibleIndices((prev) => [...prev, index]);
            }
          }
        });
      },
      { threshold: 0.1 }
    ); // Adjust threshold as needed

    cardsRef.current.forEach((card) => {
      if (card) {
        observer.observe(card);
      }
    });

    return () => {
      cardsRef.current.forEach((card) => {
        if (card) {
          observer.unobserve(card);
        }
      });
    };
  }, [visibleIndices]);

  useEffect(() => {
    const containerObserver = new IntersectionObserver(
      (entries) => {
        entries.forEach((entry) => {
          if (entry.isIntersecting) {
            setIsInView(true);
          } else {
            setIsInView(false);
          }
        });
      },
      { threshold: 0.1 } // Adjust threshold as needed
    );

    if (containerRef.current) {
      containerObserver.observe(containerRef.current);
    }

    return () => {
      if (containerRef.current) {
        containerObserver.unobserve(containerRef.current);
      }
    };
  }, []);

  return (
    <>
      <Box>
        <Container
          maxWidth={"xl"}
          sx={{
            px: { xs: 5, sm: 10, lg: 15, xl: 20 },
            pt: { xs: 10, sm: 10, lg: 15, xl: 20 },
          }}
        >
          <Grid container>
            <Grid item xs={12}>
              <ScrollAnimation
                animateIn="fadeIn"
                animateOut="fadeOut"
                animateOnce
              >
                <Typography
                  gutterBottom
                  sx={{
                    fontSize: {
                      xs: "26px",
                      sm: "36px",
                      md: "46px",
                      lg: "56px",
                    },
                    lineHeight: {
                      xs: "34px",
                      sm: "45px",
                      md: "60px",
                      lg: "70px",
                    },
                    fontWeight: 500,
                    color: "#201D28",
                  }}
                >
                  Unlock the future of innovation
                </Typography>
                <Typography
                  sx={{
                    fontSize: { xs: "14px", sm: "16px", lg: "18px" },
                    lineHeight: {
                      xs: "22px",
                      sm: "25px",
                      lg: "30px",
                    },
                    fontWeight: 500,
                    color: "#646271",
                  }}
                >
                  Start your IT transformation journey now!
                </Typography>
              </ScrollAnimation>
            </Grid>
            <Grid
              item
              xs={12}
              sx={{ display: "flex", justifyContent: "end", py: 3 }}
            >
              <Box sx={{ height: "40px", width: "40px" }}>
                <img
                  src={ellipseImg1}
                  alt="ellipseImg1"
                  className="zoom-animation2"
                />
              </Box>
            </Grid>
            <Grid
              item
              container
              xs={12}
              rowGap={{ xs: 6, md: 0 }}
              columnSpacing={{ md: 5 }}
            >
              {innovations.map((item, index) => (
                <Grid
                  item
                  xs={12}
                  md={4}
                  key={index}
                  ref={(el) => (cardsRef.current[index] = el)}
                  className={`card ${
                    visibleIndices.includes(index) ? "in-view" : ""
                  }`}
                >
                  <Card
                    sx={{
                      border: "1px solid #CDCDE0",
                      borderRadius: "19px",
                      boxShadow: "none",
                      height: "100%",
                      display: "flex",
                      width: "100%",
                      transition: "all 0.3s ease-in-out", // Smooth transition
                      "&:hover": {
                        borderColor: "transparent", // Change border color instead of removing it
                        bgcolor: "#F5F5F9", // Smooth background color transition
                        boxShadow: "0px 4px 7px rgba(0, 0, 0, 0.2)",
                      },
                      textDecoration: "none",
                    }}
                    component={Link}
                    to={item.path && item.path}
                  >
                    <CardContent
                      sx={{
                        display: "flex",
                        flexDirection: "column",
                        justifyContent: "space-between",
                      }}
                    >
                      <Box
                        sx={{
                          display: "flex",
                          flexDirection: "column",
                          gap: { xs: 3, sm: 4 },
                        }}
                      >
                        <Typography
                          sx={{
                            fontSize: {
                              xs: "20px",
                              sm: "24px",
                              md: "34px",
                              lg: "44px",
                            },
                            lineHeight: {
                              xs: "25px",
                              sm: "35px",
                              md: "45px",
                              lg: "61px",
                            },
                            fontWeight: 500,
                            color: "#602DE1",
                          }}
                        >
                          {item.title}
                        </Typography>
                        <Typography
                          sx={{
                            fontSize: {
                              xs: "14px",
                              sm: "16px",
                              md: "18px",
                              lg: "24px",
                            },
                            lineHeight: { xs: "22px", sm: "25px", lg: "30px" },
                            fontWeight: 500,
                            color: "#646271",
                            // textAlign: "justify",
                          }}
                        >
                          {item.description}
                        </Typography>
                      </Box>
                    </CardContent>
                  </Card>
                </Grid>
              ))}
            </Grid>
          </Grid>
        </Container>
        <Box sx={{ py: 4, ml: { xs: 2, sm: 9, xl: 50 } }}>
          <Box sx={{ height: "57px", width: "57px" }}>
            <img
              src={ellipseImg2}
              alt="ellipseImg2"
              className="zoom-animation1"
            />
          </Box>
        </Box>
      </Box>
    </>
  );
};

export default UnlockFutureInnovation;
